mapper.select:
SELECT * FROM (
SELECT '${VALID_STATUS_01}' validStatus, wtpd.F_TRADE_ID fTradeId, wtpd.TRADE_ID tradeId, wtpda.ENTRUST_ID entrustId, pp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, wtpdo.REPO_TYPE repoType, wtpd.FINPROD_ID finprodId, wtpdo.TERM_TYPE termTypeReback, wptpd.BACK_LEND_DIRECTION ps, wtpd.TRADE_DATE tradeDate, wtpd.PRIN_AMT prinAmt, wtpd.CCY ccy, wtpd.REMARK remark, wtpd.WORKFLOW_ID workflowId, wtpd.WORKFLOW_STATUS workflowStatus, dict.item_value tradeMarket FROM WFL_TRD_PRODUCT_DEAL wtpd LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD wtpda ON wtpda.TRADE_ID = wtpd.TRADE_ID LEFT JOIN PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL_OTH wtpdo ON wtpdo.TRADE_ID = wtpd.TRADE_ID LEFT JOIN WFL_PA_TRD_PRODUCT_DEAL wptpd ON wptpd.TRADE_ID = wtpd.TRADE_ID LEFT JOIN sys_datadict_list dict ON wtpd.trade_market=dict.item_code and dict.dict_code='TRADE_PLACE' WHERE pp.INVEST_YESORNO='Y' AND wtpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) and wtpd.ps not in (#{ps_T22},#{ps_T23})
AND (pp.PORTFOLIO_ID IN ( SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND (pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item} )
AND wtpda.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND wptpd.PA_BUSS_TYPE IN (#{PINAN_BUSINESS_TYPE_19}, #{PINAN_BUSINESS_TYPE_20})
AND wtpdo.REPO_TYPE = #{repoType}
and wptpd.BACK_LEND_DIRECTION = #{ps}
AND wtpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND wtpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and (wtpd.IS_CANCEL is null or wtpd.IS_CANCEL = #{YES_NO_NO}) and wtpd.TRADE_STATUS = #{TRADE_STATUS_01}
and wtpd.f_trade_id=#{fTradeId}
UNION ALL SELECT '${VALID_STATUS_02}' validStatus, tpd.F_TRADE_ID fTradeId, tpd.TRADE_ID tradeId, tpda.ENTRUST_ID entrustId, pp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, fpt.TYPE_6 repoType, tpd.FINPROD_ID finprodId, ftp.TERM_TYPE termTypeReback, ptpd.BACK_LEND_DIRECTION ps, tpd.TRADE_DATE tradeDate, tpd.PRIN_AMT prinAmt, tpd.CCY ccy, tpd.REMARK remark, '' workflowId, '' workflowStatus, dict.item_value tradeMarket FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID LEFT JOIN PTL_TRADE PT ON tpd.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = tpd.TRADE_ID AND fpt.BRANCH = #{BRANCH_0} LEFT JOIN FIN_TRADE_PRODUCT ftp ON ftp.FINPROD_ID = tpd.TRADE_ID AND fpt.BRANCH = #{BRANCH_0} LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = tpd.TRADE_ID LEFT JOIN sys_datadict_list dict ON tpd.trade_market=dict.item_code and dict.dict_code='TRADE_PLACE' where pp.INVEST_YESORNO='Y' and tpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) and tpd.ps not in (#{ps_T22},#{ps_T23})
AND (pp.PORTFOLIO_ID IN ( SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND (pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item} )
AND tpda.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND ptpd.PA_BUSS_TYPE IN (#{PINAN_BUSINESS_TYPE_19}, #{PINAN_BUSINESS_TYPE_20})
AND fpt.TYPE_6 = #{repoType}
and ptpd.BACK_LEND_DIRECTION = #{ps}
AND tpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND tpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
AND (tpd.IS_CANCEL is null or tpd.IS_CANCEL = #{YES_NO_NO}) AND tpd.TRADE_STATUS = #{TRADE_STATUS_01}
and tpd.f_trade_id=#{fTradeId}
UNION ALL SELECT '${VALID_STATUS_03}' validStatus, tpd.F_TRADE_ID fTradeId, tpd.TRADE_ID tradeId, tpda.ENTRUST_ID entrustId, pp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, fpt.TYPE_6 repoType, tpd.FINPROD_ID finprodId, ftp.TERM_TYPE termTypeReback, ptpd.BACK_LEND_DIRECTION ps, tpd.TRADE_DATE tradeDate, tpd.PRIN_AMT prinAmt, tpd.CCY ccy, tpd.REMARK remark, '' workflowId, '' workflowStatus, dict.item_value tradeMarket FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpda.TRADE_ID = tpd.TRADE_ID LEFT JOIN PTL_TRADE PT ON tpd.P_TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON ( (tpd.TRADE_STATUS = #{TRADE_STATUS_01} AND fpt.FINPROD_ID = tpd.TRADE_ID) OR (tpd.TRADE_STATUS = #{TRADE_STATUS_03} AND fpt.FINPROD_ID = SUBSTR(tpd.TRADE_ID, 1, LENGTH(tpd.TRADE_ID)-1)) ) AND fpt.BRANCH = #{BRANCH_0} LEFT JOIN FIN_TRADE_PRODUCT ftp ON ( (tpd.TRADE_STATUS = #{TRADE_STATUS_01} AND ftp.FINPROD_ID = tpd.TRADE_ID) OR (tpd.TRADE_STATUS = #{TRADE_STATUS_03} AND ftp.FINPROD_ID = SUBSTR(tpd.TRADE_ID, 1, LENGTH(tpd.TRADE_ID)-1)) ) AND fpt.BRANCH = #{BRANCH_0} LEFT JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = tpd.TRADE_ID LEFT JOIN sys_datadict_list dict ON tpd.trade_market=dict.item_code and dict.dict_code='TRADE_PLACE' where pp.INVEST_YESORNO='Y' and tpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) and tpd.ps not in (#{ps_T22},#{ps_T23})
AND (pp.PORTFOLIO_ID IN ( SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND (pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item} )
AND tpda.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND ptpd.PA_BUSS_TYPE IN (#{PINAN_BUSINESS_TYPE_19}, #{PINAN_BUSINESS_TYPE_20})
AND fpt.TYPE_6 = #{repoType}
and ptpd.BACK_LEND_DIRECTION = #{ps}
AND tpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND tpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
AND tpd.TRADE_STATUS = #{TRADE_STATUS_03}
and tpd.f_trade_id=#{fTradeId}
) ORDER BY tradeDate DESC, tradeId DESC
